// Metadata returns fresh policy metadata for every generated tool.
func Metadata() []policy.ToolMetadata {
	return []policy.ToolMetadata{
		{
			ID:          ApproveMerge,
			Title:       "Approve Merge",
			Description: "Approve the confirmed Change Card revision after its CP4 verification report passed for the candidate commit. Requires a promotion target, configured with surla promotion set.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          CheckProject,
			Title:       "Check Project",
			Description: "Run the workspace's Go tests on the current uncommitted files in an isolated Linux container. No input. Returns passed and a message with the first failure; when it says the output was cut, read the rest with read_check_output(op_id). If the message says go.sum or go.work.sum needs entries or go.mod needs an update, call update_dependencies and check again.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ConfigureModel,
			Title:       "Configure Model",
			Description: "Switch the model provider and model name (such as anthropic/claude-sonnet-4-6 or openai/gpt-5.4-mini, using the API key in the project server's environment) or attach a running model gateway address, without restarting the project server. Live targets that start_live_target starts afterwards plan with this model.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ConfirmIntent,
			Title:       "Confirm Intent",
			Description: "Confirm or refine Checkpoint 1 ambiguity answers and example checks for the card's current request_revision, or adopt a waiting proposed revision by naming its request_revision with answers to its questions. A decision that no option expresses goes to the guide, which records it with revise_change; the user then confirms the resulting revision.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          DeclineRevision,
			Title:       "Decline Revision",
			Description: "Decline the revision the guide proposed beside a confirmed Change Card, naming proposed_revision.request_revision; the confirmed revision stays in force.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          Diff,
			Title:       "Diff",
			Description: "Compute structural Goa design and go.mod dependency diffs.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          DraftOverride,
			Title:       "Draft Override",
			Description: "Hot-reload a prompt template in 0s or flag a compiled business rule change. A prompt template needs a running live target: call start_live_target with a candidate commit first.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          GenerateCode,
			Title:       "Generate Code",
			Description: "Regenerate code from local edited design files without uploading source. Omit target for the application, or use target eval for the public local eval/ module. Return sorted module-relative files_written and warnings. This compiles the design only; run check_project to build and test the application before verification. Fix a rejected design and call again on the same server.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          GetBuild,
			Title:       "Get Build",
			Description: "Read a change's build: whether the user started one, the revision built, whether each role read its assignment, the test writer's state, and whether the build is for the change's revision in force.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          GetBuilderAssignment,
			Title:       "Get Builder Assignment",
			Description: "Read your build assignment for a change: the change_id and request_revision to build in the project folder. Verification of that revision judges the work: pass both to verify_change.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          GetChange,
			Title:       "Get Change",
			Description: "Read the current Checkpoint 1 Change Card, its request_revision, and any proposed revision waiting beside it.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          GetStoryRefresh,
			Title:       "Get Story Refresh",
			Description: "Read the current Story refresh operation for the bound workspace: op_id, state (none, running, succeeded, or failed), snapshot_digest, stories, or diagnostic. Takes no input. When state is none, call refresh_story first.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          GetTestWriterAssignment,
			Title:       "Get Test Writer Assignment",
			Description: "Read your test assignment for a change: the working folder, the design and Story as agreed, one required test per finished flow, and your state with any findings to fix. Align the service interface in your copy with the agreed design and write tests inside its test module. When your tests are finished, call report_tests_finished with change_id and request_revision.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          GetVerification,
			Title:       "Get Verification",
			Description: "Read the state of a CP4 verification run started by verify_change.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          InitProject,
			Title:       "Init Project",
			Description: "Initialize a new Surla starter project inside the bound workspace directory, create its initial Git commit, and switch the server's active workspace to that project. Returns the created commit ID in commit for start_live_target and verify_change.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ListBuilderAssignments,
			Title:       "List Builder Assignments",
			Description: "List your build assignments: change_id, request_revision and whether you read each. Read one in full with get_builder_assignment(change_id).",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ListChanges,
			Title:       "List Changes",
			Description: "List this project's Change Cards, most recently saved first, with each card's summary, status and request_revision in force, its proposed_revision (the request_revision of a revision proposed beside a confirmed card, while it waits for the user to adopt or decline it), latest verification run state and last save time. Read one card, with any proposed revision, with get_change(change_id).",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ListTestWriterAssignments,
			Title:       "List Test Writer Assignments",
			Description: "List your test assignments: change_id, request_revision, state and whether you read each. Read one in full with get_test_writer_assignment(change_id).",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ListTraces,
			Title:       "List Traces",
			Description: "Read the project's saved operation diagnostics, newest first. status filters all spans, recorded errors, or spans without an error status. Empty spans with has_more true still leaves older history to examine: pass next_cursor as cursor with the same filter. Omit cursor to refresh. Summaries exclude raw errors and inputs; unset status does not prove success. Authenticated HTTP/MCP domain calls have a request boundary span and may also have child domain spans. Waiting reads do not enter the private history. Requests rejected before authentication or decoding and separate verification processes are absent. not_implemented means the server operator must enable recording; it is not an empty history.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ListVerifications,
			Title:       "List Verifications",
			Description: "List all CP4 verification runs started for a Change Card, newest first.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          PreviewArchitecture,
			Title:       "Preview Architecture",
			Description: "Preview Checkpoint 2 C4 container topology and Goa-AI guardrails for a confirmed Change Card. Surla reads the candidate module from the bound workspace. It reports what the design declares; it does not compare the design with the Change Card's requirements.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ProposeChange,
			Title:       "Propose Change",
			Description: "Propose a feature change as a Checkpoint 1 Change Card. Read the target's design/*.go and the surla://golden-path playbook first, then send the request in prompt with your analysis of it: a summary, the open questions only the requester can answer (an empty list when none), concrete examples that become checks, and the existing behaviors the change must keep. When adopting a workspace Story, pass the succeeded refresh_story operation's op_id in story_refresh_op_id. Surla assigns the IDs and request_revision and saves the card; every card awaits the user's confirmation, including a card without open questions. When story_refresh_op_id is omitted and a workspace is bound, Surla records design/*.go from the bound workspace.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ReadCheckOutput,
			Title:       "Read Check Output",
			Description: "Read the next page of a check_project or update_dependencies output. Pass op_id from that result and next_cursor from the previous page; omit cursor for the first page. dropped_bytes > 0 means part of the output was not captured.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          RefreshStory,
			Title:       "Refresh Story",
			Description: "Start or reuse a sandboxed Story evaluation of the bound workspace's current design files and return op_id, state, and snapshot_digest promptly. Takes no input. Poll get_story_refresh until state is succeeded or failed.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ReportTestsFinished,
			Title:       "Report Tests Finished",
			Description: "Report that your tests for the assignment's change_id and request_revision are finished. Surla records the report as reported, without checking the tests, and returns the assignment's new state.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          ReviseChange,
			Title:       "Revise Change",
			Description: "Revise an existing Checkpoint 1 Change Card with updated requirements. Name the latest revision you read in request_revision: proposed_revision.request_revision when get_change shows a proposal waiting, otherwise the card's. Send the revised request in prompt with a new analysis made against that revision and the target's design: keep or edit each of its examples through prior_id, list the dropped ones in removed_example_ids, and restate the confirmed decisions that still hold in summary, examples or preserved_behaviors. Pass story_refresh_op_id from a succeeded refresh_story operation to adopt an updated workspace Story, or omit it to keep the Story and design source of the revision you revise. On a confirmed card your revision becomes a proposal beside the confirmed one, which stays in force until the user adopts or declines the proposal on the views page; you cannot withdraw a proposal, only replace it by revising again.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          StartLiveTarget,
			Title:       "Start Live Target",
			Description: "Build a candidate commit and run it as this server's live CP3 target so draft_override can try prompt text on it. This first stops the target already running, which discards every prompt draft applied to it, even if the new build then fails. Prompt text survives only when it is committed. Requires a committed starter project in the bound workspace or verification settings installed with surla verification set.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          StopLiveTarget,
			Title:       "Stop Live Target",
			Description: "Stop this server's live CP3 target, if one runs. This discards every prompt draft applied to it; prompt text survives only when it is committed.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          UpdateDependencies,
			Title:       "Update Dependencies",
			Description: "Add missing requirements and checksums for the workspace's Go modules (go mod tidy) and write the changed go.mod, go.sum and go.work.sum. No input. Call it when check_project reports a missing go.sum or go.work.sum entry or a needed go.mod update, then call check_project again.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
		{
			ID:          VerifyChange,
			Title:       "Verify Change",
			Description: "Start CP4 verification of a candidate commit for the confirmed Change Card revision; returns a run_id to read with get_verification. Requires a committed starter project in the bound workspace or verification settings installed with surla verification set.",
			Tags:        []string{},
			BudgetClass: policy.ToolBudgetClassBudgeted,
		},
	}
}

